package com.badrulamin.University_Management.service;
import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.AcademicResult; import com.badrulamin.University_Management.repository.AcademicResultRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;  import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import java.util.List;  @Service @RequiredArgsConstructor @Transactional public class AcademicResultService {      private final AcademicResultRepository academicResultRepository;      public Page<AcademicResult> findAll(Pageable pageable) {         return academicResultRepository.findAll(pageable);     }      public AcademicResult findById(Long id) {         return academicResultRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AcademicResult", "id", id));     }      public AcademicResult save(AcademicResult academicResult) {         return academicResultRepository.save(academicResult);     }      public AcademicResult update(Long id, AcademicResult academicResult) {         findById(id);         academicResult.setId(id);         return academicResultRepository.save(academicResult);     }      public void delete(Long id) {         findById(id);         academicResultRepository.deleteById(id);     } }